// Generated by scripts/build.py from n8n/code/. Prefer editing the sources and rebuilding.

// ===== secrev settings (edit here) =====
const CONFIG = {
  "github_api_url": "https://api.github.com",
  "github_installation_id": "REPLACE_WITH_INSTALLATION_ID",
  "allowed_repos": [],
  "skip_drafts": true,
  "sweeper_after_minutes": 20,
  "sweeper_max_age_hours": 72,
  "sweeper_max_reviews": 5
};
// =======================================

// secrev-sweeper › Config
return [{
  json: {
    config: CONFIG, installation_id: Number(CONFIG.github_installation_id),
    permissions: { pull_requests: 'read', contents: 'read', actions: 'read', metadata: 'read' },
  },
}];

// Generated by scripts/build.py from n8n/code/. Prefer editing the sources and rebuilding.

// secrev-sweeper › Expand repos
const cfg = $('Config').first().json.config;
const repos = [];
for (const it of $input.all()) {
  for (const r of ((it.json || {}).repositories || [])) {
    if (r.archived || r.disabled) continue;
    if (cfg.allowed_repos.length && !cfg.allowed_repos.includes(r.full_name)) continue;
    repos.push({ owner: r.owner.login, repo: r.name });
  }
}
return repos.map((r) => ({ json: r }));

// Generated by scripts/build.py from n8n/code/. Prefer editing the sources and rebuilding.

// secrev-sweeper › Pick candidates
// Open PRs quiet for at least sweeper_after_minutes (normal reviews arrive well before
// that) and active within sweeper_max_age_hours (so enabling secrev does not review
// every old PR at once).
const cfg = $('Config').first().json.config;
const now = Date.now();
const out = [];
for (const it of $input.all()) {
  const pr = it.json || {};
  if (typeof pr.number !== 'number' || pr.state !== 'open' || !pr.head || !pr.base) continue;
  if (pr.draft && cfg.skip_drafts) continue;
  const age = now - Date.parse(pr.updated_at);
  if (age < cfg.sweeper_after_minutes * 60000 || age > cfg.sweeper_max_age_hours * 3600000) continue;
  out.push({ owner: pr.base.repo.owner.login, repo: pr.base.repo.name, pr_number: pr.number, head_sha: pr.head.sha });
}
return out.map((c) => ({ json: c }));

